from itertools import islice, tee

def unique_justseen(iterable, key=None):
    """Yields elements in order, ignoring serial duplicates

    >>> list(unique_justseen('AAAABBBCCDAABBB'))
    ['A', 'B', 'C', 'D', 'A', 'B']
    >>> list(unique_justseen('ABBCcAD', str.lower))
    ['A', 'B', 'C', 'A', 'D']

    """
    def pairwise(iterable):
        """s -> (s0,s1), (s1,s2), (s2, s3), ..."""
        a, b = tee(iterable)
        next(b, None)
        return zip(a, b)

    if key is None:
        for item, next_item in pairwise(iterable):
            if item != next_item:
                yield item
        yield iterable[-1]
    else:
        for item, next_item in pairwise(map(key, iterable)):
            if item != next_item:
                yield iterable[next(iterable).index(next_item)]
        yield iterable[-1]
